"""POST /v1/audit/manifest/verify-batch 批量审计清单验真端到端测试。

直接运行：python3 tests/audit_manifest_verify_batch_test.py
不依赖第三方测试框架，仅用标准库 + cryptography。
"""

import copy
import json
import os
import subprocess
import sys
import tempfile
import threading
import time
import urllib.error
import urllib.request
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

MANIFEST_PATH = "/v1/audit/manifest"
BATCH_PATH = "/v1/audit/manifest/verify-batch"
VERIFY_PATH = "/v1/audit/manifest/verify"


def _http(method, url, payload=None, headers=None, raw=None):
    if raw is not None:
        data = raw
    else:
        data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(url, data=data, method=method)
    if data is not None:
        req.add_header("Content-Type", "application/json")
    for key, value in (headers or {}).items():
        req.add_header(key, value)
    try:
        with urllib.request.urlopen(req) as resp:
            return resp.status, resp.read()
    except urllib.error.HTTPError as exc:
        return exc.code, exc.read()


def wait_up(port, timeout=10.0):
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            _http("GET", f"http://127.0.0.1:{port}/health")
            return True
        except OSError:
            time.sleep(0.1)
    return False


def main():
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

